BEGIN;
CREATE SCHEMA IF NOT EXISTS modern;
REVOKE ALL ON SCHEMA modern FROM PUBLIC, anon, authenticated;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname='modern_app') THEN CREATE ROLE modern_app NOLOGIN NOBYPASSRLS; END IF; END $$;
GRANT modern_app TO postgres;
GRANT USAGE ON SCHEMA modern TO modern_app;
CREATE TABLE IF NOT EXISTS modern.clients(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,national_id text UNIQUE NOT NULL,phone text NOT NULL,email text,notes text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS modern.users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,email text UNIQUE NOT NULL,role text NOT NULL CHECK(role IN ('manager','secretary','accountant','architect','civil_engineer','draftsman','municipality_draftsman','site_supervisor','client')),client_id uuid REFERENCES modern.clients,active boolean NOT NULL DEFAULT true,must_change_password boolean NOT NULL DEFAULT true,password_hash text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),CHECK((role='client')=(client_id IS NOT NULL)));
CREATE TABLE IF NOT EXISTS modern.sessions(token_hash text PRIMARY KEY,user_id uuid NOT NULL REFERENCES modern.users ON DELETE CASCADE,expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS sessions_user ON modern.sessions(user_id);
CREATE TABLE IF NOT EXISTS modern.rate_limits(key text PRIMARY KEY,count integer NOT NULL,expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS modern.projects(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code text UNIQUE NOT NULL DEFAULT ('MOD-'||upper(substr(gen_random_uuid()::text,1,8))),name text NOT NULL,client_id uuid NOT NULL REFERENCES modern.clients,location text NOT NULL,description text NOT NULL DEFAULT '',stage integer NOT NULL DEFAULT 0 CHECK(stage BETWEEN 0 AND 9),status text NOT NULL DEFAULT 'active',due_date date,contract_value numeric(14,3) NOT NULL DEFAULT 0 CHECK(contract_value>=0),visibility jsonb NOT NULL DEFAULT '{}',version integer NOT NULL DEFAULT 1,municipality_decision text,closure_decision text,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS projects_client ON modern.projects(client_id);
CREATE TABLE IF NOT EXISTS modern.assignments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES modern.projects,user_id uuid NOT NULL REFERENCES modern.users,stage integer NOT NULL CHECK(stage BETWEEN 1 AND 8),UNIQUE(project_id,stage));
CREATE INDEX IF NOT EXISTS assignments_user ON modern.assignments(user_id,project_id);
CREATE TABLE IF NOT EXISTS modern.reports(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES modern.projects,title text NOT NULL,notes text NOT NULL DEFAULT '',visit_date date NOT NULL,created_by uuid NOT NULL REFERENCES modern.users,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS modern.documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES modern.projects,name text NOT NULL,category text NOT NULL CHECK(category IN ('architecture','civil','drawings_2d','drawings_3d','municipality','site_photos','site_reports','contract','supervision_contract','municipality_letters','receipts')),mime_type text NOT NULL,size integer NOT NULL CHECK(size>0 AND size<=15728640),content bytea NOT NULL,uploaded_by uuid NOT NULL REFERENCES modern.users,report_id uuid REFERENCES modern.reports,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS modern.quotations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES modern.projects,amount numeric(14,3) NOT NULL CHECK(amount>0),notes text NOT NULL DEFAULT '',version integer NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(project_id,version));
CREATE TABLE IF NOT EXISTS modern.allocations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES modern.projects,stage integer NOT NULL CHECK(stage BETWEEN 0 AND 9),percentage numeric(6,3) NOT NULL CHECK(percentage>0 AND percentage<=100),due_date date,UNIQUE(project_id,stage));
CREATE TABLE IF NOT EXISTS modern.payments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES modern.projects,amount numeric(14,3) NOT NULL CHECK(amount>0),reference text NOT NULL,paid_at date NOT NULL,notes text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS modern.tasks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES modern.projects,title text NOT NULL,assigned_to uuid NOT NULL REFERENCES modern.users,due_date date,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','in_progress','completed')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS modern.audit(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),actor_id uuid REFERENCES modern.users,actor_name text NOT NULL,action text NOT NULL,project_id uuid REFERENCES modern.projects,details jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS modern.inquiries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,phone text NOT NULL,service text NOT NULL,message text NOT NULL,status text NOT NULL DEFAULT 'new',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS modern.portfolio(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),title text NOT NULL,category text NOT NULL,location text NOT NULL,description text NOT NULL,image_url text NOT NULL,published boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS modern.notification_settings(id boolean PRIMARY KEY DEFAULT true CHECK(id),enabled boolean NOT NULL DEFAULT false,events jsonb NOT NULL DEFAULT '{}',templates jsonb NOT NULL DEFAULT '{}');
INSERT INTO modern.notification_settings(id) VALUES(true) ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS modern.notification_preferences(client_id uuid PRIMARY KEY REFERENCES modern.clients,enabled boolean NOT NULL DEFAULT true,events jsonb NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS modern.notifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid REFERENCES modern.projects,client_id uuid NOT NULL REFERENCES modern.clients,event text NOT NULL,body text NOT NULL DEFAULT '',status text NOT NULL DEFAULT 'queued',dedup_key text UNIQUE NOT NULL DEFAULT gen_random_uuid()::text,attempts integer NOT NULL DEFAULT 0,last_error text,next_attempt_at timestamptz NOT NULL DEFAULT now(),lease_token uuid,lease_until timestamptz,provider_message_id text UNIQUE,sent_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS notifications_due ON modern.notifications(next_attempt_at,created_at) WHERE status IN ('queued','pending','failed');
CREATE INDEX IF NOT EXISTS notifications_lease ON modern.notifications(lease_until) WHERE status='sending';
CREATE TABLE IF NOT EXISTS modern.waha_webhook_events(id text PRIMARY KEY,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS modern.waha_sessions(name text PRIMARY KEY,status text NOT NULL,updated_at timestamptz NOT NULL DEFAULT now());
CREATE OR REPLACE FUNCTION modern.actor_id() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('modern.user_id',true),'')::uuid $$;
CREATE OR REPLACE FUNCTION modern.actor_role() RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$ SELECT role FROM modern.users WHERE id=modern.actor_id() AND active $$;
CREATE OR REPLACE FUNCTION modern.can_project(pid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$ SELECT EXISTS(SELECT 1 FROM modern.projects p JOIN modern.users u ON u.id=modern.actor_id() AND u.active WHERE p.id=pid AND (u.role IN ('manager','secretary','accountant') OR (u.role='client' AND p.client_id=u.client_id) OR (u.role NOT IN ('client','site_supervisor') AND EXISTS(SELECT 1 FROM modern.assignments a WHERE a.project_id=p.id AND a.user_id=u.id)) OR (u.role='site_supervisor' AND p.stage>=7 AND EXISTS(SELECT 1 FROM modern.assignments a WHERE a.project_id=p.id AND a.user_id=u.id AND a.stage=7)))) $$;
CREATE OR REPLACE FUNCTION modern.visible(pid uuid,key text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$ SELECT coalesce((visibility->>key)::boolean,false) FROM modern.projects WHERE id=pid AND modern.can_project(pid) $$;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA modern FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON ALL FUNCTIONS IN SCHEMA modern TO modern_app;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['users','clients','projects','assignments','reports','documents','quotations','allocations','payments','tasks','audit','inquiries','portfolio','notifications','notification_preferences','notification_settings','waha_webhook_events','waha_sessions'] LOOP EXECUTE format('ALTER TABLE modern.%I ENABLE ROW LEVEL SECURITY',t); END LOOP; END $$;
GRANT SELECT ON modern.users TO modern_app;
GRANT SELECT,INSERT,UPDATE ON modern.clients,modern.projects,modern.assignments,modern.tasks,modern.inquiries,modern.portfolio,modern.notification_preferences,modern.notification_settings,modern.waha_sessions TO modern_app;
GRANT SELECT,INSERT ON modern.reports,modern.quotations,modern.payments,modern.audit,modern.notifications TO modern_app;
GRANT SELECT,INSERT,DELETE ON modern.allocations TO modern_app;
GRANT DELETE ON modern.portfolio TO modern_app;
GRANT SELECT(id,project_id,name,category,mime_type,size,uploaded_by,report_id,created_at,content),INSERT ON modern.documents TO modern_app;
CREATE POLICY users_read ON modern.users FOR SELECT TO modern_app USING(id=modern.actor_id() OR modern.actor_role() IN ('manager','secretary'));
CREATE POLICY clients_access ON modern.clients TO modern_app USING(modern.actor_role() IN ('manager','secretary','accountant')) WITH CHECK(modern.actor_role() IN ('manager','secretary'));
CREATE POLICY projects_read ON modern.projects FOR SELECT TO modern_app USING(modern.can_project(id));
CREATE POLICY projects_insert ON modern.projects FOR INSERT TO modern_app WITH CHECK(modern.actor_role() IN ('manager','secretary'));
CREATE POLICY projects_update ON modern.projects FOR UPDATE TO modern_app USING(modern.can_project(id) AND modern.actor_role() NOT IN ('client')) WITH CHECK(modern.can_project(id) AND modern.actor_role()<>'client');
CREATE POLICY assignments_read ON modern.assignments FOR SELECT TO modern_app USING(modern.can_project(project_id) AND modern.actor_role()<>'client');
CREATE POLICY assignments_write ON modern.assignments FOR ALL TO modern_app USING(modern.actor_role() IN ('manager','secretary')) WITH CHECK(modern.actor_role() IN ('manager','secretary'));
CREATE POLICY reports_read ON modern.reports FOR SELECT TO modern_app USING(modern.can_project(project_id) AND (modern.actor_role()<>'client' OR modern.visible(project_id,'site_reports')));
CREATE POLICY reports_insert ON modern.reports FOR INSERT TO modern_app WITH CHECK(modern.can_project(project_id) AND modern.actor_role() IN ('manager','site_supervisor'));
CREATE POLICY documents_read ON modern.documents FOR SELECT TO modern_app USING(modern.can_project(project_id) AND (modern.actor_role()<>'client' OR modern.visible(project_id,category)));
CREATE POLICY documents_insert ON modern.documents FOR INSERT TO modern_app WITH CHECK(modern.can_project(project_id) AND modern.actor_role()<>'client');
DO $$ DECLARE t text; k text; BEGIN FOREACH t IN ARRAY ARRAY['quotations','allocations','payments'] LOOP k:=CASE t WHEN 'quotations' THEN 'quotation' WHEN 'allocations' THEN 'payment_schedule' ELSE 'payments' END; EXECUTE format('CREATE POLICY finance_read ON modern.%I FOR SELECT TO modern_app USING(modern.can_project(project_id) AND (modern.actor_role() IN (''manager'',''secretary'',''accountant'') OR (modern.actor_role()=''client'' AND modern.visible(project_id,%L))))',t,k); EXECUTE format('CREATE POLICY finance_insert ON modern.%I FOR INSERT TO modern_app WITH CHECK(modern.actor_role() IN (''manager'',''accountant''))',t); END LOOP; END $$;
CREATE POLICY allocations_delete ON modern.allocations FOR DELETE TO modern_app USING(modern.actor_role() IN ('manager','accountant'));
CREATE POLICY tasks_read ON modern.tasks FOR SELECT TO modern_app USING(modern.can_project(project_id) AND modern.actor_role()<>'client');
CREATE POLICY tasks_insert ON modern.tasks FOR INSERT TO modern_app WITH CHECK(modern.actor_role() IN ('manager','secretary'));
CREATE POLICY tasks_update ON modern.tasks FOR UPDATE TO modern_app USING(modern.actor_role() IN ('manager','secretary') OR assigned_to=modern.actor_id()) WITH CHECK(modern.actor_role() IN ('manager','secretary') OR assigned_to=modern.actor_id());
CREATE POLICY audit_read ON modern.audit FOR SELECT TO modern_app USING(modern.actor_role()='manager' OR (modern.actor_role()='secretary' AND project_id IS NOT NULL));
CREATE POLICY audit_insert ON modern.audit FOR INSERT TO modern_app WITH CHECK(actor_id=modern.actor_id() AND modern.actor_role()<>'client');
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['inquiries','portfolio','notifications','notification_preferences','notification_settings','waha_sessions'] LOOP EXECUTE format('CREATE POLICY admin_access ON modern.%I TO modern_app USING(modern.actor_role()=''manager'') WITH CHECK(modern.actor_role()=''manager'')',t); END LOOP; END $$;
CREATE POLICY notifications_insert ON modern.notifications FOR INSERT TO modern_app WITH CHECK(modern.can_project(project_id) AND modern.actor_role()<>'client');
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['reports','documents','quotations','allocations','payments','tasks','audit','notifications'] LOOP EXECUTE format('CREATE INDEX IF NOT EXISTS %I ON modern.%I(project_id)',t||'_project',t); END LOOP; END $$;
COMMIT;
